class HitClassifier(nn.Module):
    def __init__(self, in_features):
        super().__init__()
        # DBSCAN hyperparameters
        self.eps = 0.02
        self.min_samples = 4

    def forward(self, batch_x):
        # batch_x: torch.Tensor of shape [N_hits, F]
        X = batch_x.detach().cpu().numpy()            # shape [N_hits, 4]
        r = X[:, 0]                                   # radial coordinate, shape [N_hits]
        z = X[:, 2]                                   # z coordinate, shape [N_hits]
        # compute approximate slope z/r
        slope = z / (r + 1e-6)                        # shape [N_hits]
        # cluster on slope only
        clustering = DBSCAN(eps=self.eps, min_samples=self.min_samples)
        labels = clustering.fit_predict(slope.reshape(-1, 1))  # shape [N_hits], values -1..n_clusters-1
        # remap noise (-1) to unique clusters to ensure they're discarded (size 1)
        max_label = labels.max()
        noise_indices = np.where(labels < 0)[0]
        for i, idx in enumerate(noise_indices):
            labels[idx] = max_label + 1 + i
        # return as torch tensor
        return torch.as_tensor(labels, device=batch_x.device, dtype=torch.long)

